<script setup>
import { Link, router, usePage } from '@inertiajs/vue3';
import { reactive } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ posts: Object, filters: Object, categories: Array, statuses: Array });
const page = usePage();
const filter = reactive({ status: props.filters.status || 'all', category: props.filters.category || 'all', search: props.filters.search || '' });
const apply = () => router.get(route('redesign.doopnews'),filter,{preserveState:true});
</script>
<template><AssessmentLayout title="DoopNews" subtitle="Kelola berita dan pengumuman komunitas." breadcrumb="Komunitas & pengguna"><template #action><Link v-if="page.props.auth?.user?.role !== 'mentor'" class="primary" :href="route('redesign.doopnews.create')">Tulis berita</Link></template><section class="panel"><div class="tabs"><button v-for="status in ['all',...statuses]" :key="status" type="button" class="secondary" :aria-pressed="filter.status===status" @click="filter.status=status;apply()">{{ status === 'all' ? 'Semua' : status }}</button></div><form class="filters" @submit.prevent="apply"><input v-model="filter.search" placeholder="Cari judul atau isi" /><select v-model="filter.category"><option value="all">Semua kategori</option><option v-for="category in categories" :key="category" :value="category">{{ category }}</option></select><button class="secondary">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Judul</th><th>Kategori</th><th>Versi</th><th>Status</th><th>Penulis</th><th>Aksi</th></tr></thead><tbody><tr v-for="post in posts.data" :key="post.id"><td><strong>{{ post.title }}</strong><br><span class="muted">{{ post.excerpt }}</span></td><td>{{ post.category }}</td><td>{{ post.version_label || '—' }}</td><td>{{ post.status }}</td><td>{{ post.author?.name || '—' }}</td><td><Link v-if="page.props.auth?.user?.role !== 'mentor'" :href="route('redesign.doopnews.edit',post.slug)">Edit</Link> <button v-if="post.status!=='published'" type="button" class="secondary" @click="router.patch(route('admin.doopnews.publish',post.slug))">Publikasikan</button></td></tr><tr v-if="!posts.data?.length"><td colspan="6">Belum ada berita.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,index) in posts.links" :key="index" :href="link.url || '#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></AssessmentLayout></template>
